def Odd_Length_Sum(arr):
    total_sum = 0
    for i in range(len(arr)):
        # Calculate the sum of odd-length subarrays ending at index i
        for j in range(i+1, len(arr)+1):
            if (j - i) % 2 != 0: 
                total_sum += arr[i:j]
    return total_sum

