def second_frequent(sequence):
    # Create a dictionary to count occurrences of each character
    char_count = {}

    # Count the frequency of each character in the sequence
    for char in sequence:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find and return the second most frequent character
    max_count = 0
    second_most_common_char = ''
    for char, count in char_count.items():
        if count > max_count:
            max_count = count
            second_most_common_char = char

    return second_most_common_char

